import java.util.Scanner;

public class Main {
    static final int MAX_LIMIT = 577;
    static int n, m, Mod;
    static long[] dp = new long[MAX_LIMIT];
    static long[] dp2 = new long[MAX_LIMIT];
    static long[][] C = new long[MAX_LIMIT][MAX_LIMIT];
    static long[][] res = new long[MAX_LIMIT][MAX_LIMIT];
    static long[][] res2 = new long[MAX_LIMIT][MAX_LIMIT];

    static long computeSum(int start, int end) {
        long sum = ((long)(start + end) * (end - start + 1)) / 2;
        return sum % Mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        Mod = sc.nextInt();

        for (int i = 0; i < MAX_LIMIT; i++) {
            C[i][0] = 1;
            C[i][i] = 1;
        }
        for (int i = 1; i < MAX_LIMIT; i++) {
            for (int j = 1; j < i; j++) {
                C[j][i] = (C[j][i - 1] + C[j - 1][i - 1]) % Mod;
            }
        }

        dp[0] = 1;
        dp2[0] = 0;

        for (int length = 1; length <= n; length++) {
            for (int i = 1; i <= length; i++) {
                long sum_value = computeSum(1, i - 1) + computeSum(1, length - i);
                int total_count = length + 1;

                long val1 = ((dp[i - 1] * (long) total_count) % Mod * dp[length - i]) % Mod * C[i - 1][length - 1] % Mod;
                long val2 = (computeSum(1, i - 1) + computeSum(1, length - i)) % Mod;
                val2 = (val2 * dp[i - 1]) % Mod * dp[length - i] % Mod * C[i - 1][length - 1];

                long val3 = (dp2[i - 1] * (long) total_count) % Mod * dp[length - i] % Mod * C[i - 1][length - 1];
                long val4 = (dp2[length - i] * (long) total_count) % Mod * dp[i - 1] % Mod * C[i - 1][length - 1];

                dp[length] = (dp[length] + val1) % Mod;
                dp2[length] = (dp2[length] + val2 + val3 + val4) % Mod;
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= m && j <= i; j++) {
                res[i][j] = res[i - 1][j];
                res2[i][j] = res2[i - 1][j];
                for (int h = 1; h < j; h++) {
                    long tempRes = (res[i - h - 1][j - h] * dp[h]) % Mod * C[h][j] % Mod;
                    res[i][j] = (res[i][j] + tempRes) % Mod;

                    long tempRes2 = (res2[i - h - 1][j - h] * dp[h]) % Mod * C[h][j] % Mod;
                    res2[i][j] = (res2[i][j] + tempRes2) % Mod;

                    long tempRes3 = (res[i - h - 1][j - h] * dp2[h]) % Mod * C[h][j] % Mod;
                    res2[i][j] = (res2[i][j] + tempRes3) % Mod;
                }
                res[i][j] = (res[i][j] + dp[j]) % Mod;
                res2[i][j] = (res2[i][j] + dp2[j]) % Mod;
            }
        }

        System.out.println(res2[n][m]);
        sc.close();
    }
}
